-- 여기서 어긋난다

@Test
void 어긋남() {
    em.clear();
    Member before = queryFactory.selectFrom(member)
            .where(member.username.eq("m1")).fetchOne();
    System.out.println("고치기 전: " + before.getUsername());

    queryFactory.update(member)
            .set(member.username, "비회원")
            .where(member.age.lt(20))
            .execute();

    System.out.println("고친 뒤:   " + before.getUsername());

    Member again = queryFactory.selectFrom(member)
            .where(member.id.eq(before.getId())).fetchOne();
    System.out.println("다시 읽음: " + again.getUsername());
    System.out.println("같은 객체: " + (before == again));
}

