@Test
void DB_확인() {
    queryFactory.update(member)
            .set(member.username, "비회원")
            .where(member.age.lt(20))
            .execute();

    String db = (String) em.createNativeQuery(
            "select username from member where member_id = 1")
        .getSingleResult();
    Member ctx = queryFactory.selectFrom(member)
            .where(member.id.eq(1L)).fetchOne();

    System.out.println("DB:   " + db);
    System.out.println("객체: " + ctx.getUsername());
}

