@Test
void 서브쿼리_조건() {
    QTeam teamSub = new QTeam("teamSub");
    em.clear();

    long n = queryFactory
            .update(member)
            .set(member.age, 0)
            .where(member.team.id.in(
                    JPAExpressions.select(teamSub.id)
                            .from(teamSub)
                            .where(teamSub.name.eq("teamB"))))
            .execute();
    System.out.println("바뀐 줄: " + n);
}

