-- 안 쓴 변경이 먼저 나간다

@Test
void flush_먼저() {
    Member m = queryFactory.selectFrom(member)
            .where(member.id.eq(1L)).fetchOne();
    m.setAge(50);

    System.out.println("--- 벌크 호출 ---");
    queryFactory.update(member)
            .set(member.age, member.age.add(1))
            .where(member.id.eq(1L))
            .execute();

    Integer db = (Integer) em.createNativeQuery(
            "select age from member where member_id = 1").getSingleResult();
    System.out.println("DB: " + db);
}

